#' Plot *s2dv* climate data
#' 
#' @description Plots *s2dv_cube* gridded, polygon and point data generated by 
#' `clim4health` functions.
#'
#' @param data *s2dv_cube* object with the climate data to be plotted.
#' @param var Numerical index of the variable to be plotted. 
#' Only required if more than one variable is available.
#' @param sdate Numerical index of the forecast starting time to be plotted. Defaults 
#' to NULL (all starting dates).
#' @param time Numerical index of the time to be plotted. Defaults to NULL (all 
#' times).
#' @param ensemble Numerical index of the ensemble member to be plotted. If
#' set to TRUE, it aggregates all the ensemble members. Defaults to NULL (all 
#' times).
#' @param boundaries Polygon boundaries to add to the map.  Set to NULL for no 
#' boundaries (default), otherwise supply a polygon `sf` object or set to 
#' "countries" for coarse country boundaries.
#' @param mask_boundaries If TRUE (default), mask the data to the provided 
#' boundaries.
#' @param ensemble_fun Aggregation function used when ensemble = TRUE.
#' Defaults to the mean.
#' @param title Optional plot title.
#' @param legend Optional legend title. If NULL (default), it uses the variable
#' names.
#' @param palette GHR, RColorBrewer or colorspace palette. Use "-" before the 
#' palette name (e.g., "-Reds") to reverse it. Alternatively, a vector of
#' hex codes to create a continuous interpolated palette.
#' @param coordgrid If TRUE, display coordinate grids on the map.
#' @param ... Extra arguments indicating fixed aesthetics to be passed to 
#'`stars::geom_stars`, including `lwd`, `alpha` and `colour`.
#' @returns A plot
#' @export
#'
#' @examples 
#' library("sf")
#' 
#' # Region municipalities
#' mun_path <- paste0(getwd(), "/inst/extdata/areas/munip_vallecauca.gpkg")
#' mun <- read_sf(mun_path)
#' 
#' # Forecast
#' fcst_path <- paste0(getwd(), "/inst/extdata/forecast/")
#' fcst <- c4h_load(fcst_path, variable = "t2m", ext = 'nc')
#' c4h_plot(fcst, title = "Forecast", ensemble = TRUE) 
#' 
#' # Reanalysis
#' rean_path <- paste0(getwd(), "/inst/extdata/reanalysis/")
#' rean <- c4h_load(rean_path, variable = "t2m", ext = 'nc')
#' c4h_plot(rean, title = "Reanalysis", boundaries = mun, 
#'          mask_boundaries = TRUE, coordgrid = TRUE) 
#' 
#' # Hindcast
#' hind_path <- paste0(getwd(), "/inst/extdata/hindcast/")
#' hind <- c4h_load(hind_path, variable = "t2m", ext = 'nc')
#' c4h_plot(hind, title = "Hindcast", ensemble = TRUE)   
#'                  
#' # Stations
#' stations_path <- paste0(getwd(), "/inst/extdata/stations/")
#' stations <- c4h_load(stations_path, var = "temp_mean", ext = "csv")
#' c4h_plot(stations, title = "Stations", time = 1:2, 
#'          boundaries = mun, coordgrid = TRUE) 
#' 
#' # Spatially aggregated data
#' fcst_aggr <- c4h_space(fcst, mun)
#' c4h_plot(fcst_aggr, ensemble = 1:5, lwd = 0.1, 
#'          title = "Temp. by municipality", coordgrid = TRUE) 
c4h_plot <- function(data,
                     var = NULL,
                     sdate = NULL,
                     time = NULL,
                     ensemble = NULL,
                     ensemble_fun = mean,
                     boundaries = NULL,
                     mask_boundaries = FALSE,
                     title = NULL,
                     legend = NULL,
                     palette = "-RdBu",
                     coordgrid = FALSE,
                     ...) {
  
  # 1. Data checks ----
  
  # Get array info
  dims_data <- data$dims
  plot_data <- data$data
  
  # Requirements: var
  if(is.null(var) & dims_data["var"]>1){
    stop("More than one 'var' is available, please select one.")
  }else if(!is.null(var) & length(var)>1){
    stop("Only one 'var' is possible.")
  }else if(!is.null(var)){
    .subset_array_named(plot_data, var = var)
  }
  
  # Requirements: sdate
  if(!is.null(sdate) & !is.numeric(sdate)){
    stop("'sdate' must be of type numeric.")
  }else if(!is.null(sdate) & any(sdate > dims_data["sdate"])){
    stop(paste0("A wrong 'sdate' has been selected (possible range: 1 - ",
                dims_data["sdate"], ")."))
  }else if(is.null(sdate)){
    sdate <- 1:dims_data["sdate"]
  }
  
  # Requirements: time
  if(!is.null(time) & !is.numeric(time)){
    stop("'time' must be of type numeric.")
  }else if(!is.null(time) & any(time > dims_data["time"])){
    stop(paste0("A wrong 'time' has been selected (possible range: 1 - ",
                dims_data["time"], ")."))
  }else if(is.null(time)){
    time <- 1:dims_data["time"]
  }
  
  # Requirements: ensemble
  if(!is.null(ensemble) & !isTRUE(ensemble) & !is.numeric(ensemble)){
    stop("'ensemble' must be either TRUE, NULL, or of type numeric.")
  }else if(!is.null(ensemble) & !isTRUE(ensemble) & any(ensemble > dims_data["ensemble"])){
    stop(paste0("A wrong 'ensemble' has been selected (possible range: 1 - ",
                dims_data["time"], ")."))
  }else if(is.null(ensemble)){
    ensemble <- 1:dims_data["ensemble"]
  }
  
  # Only two dimensions can have length > 1
  if(length(sdate)>1 & length(time)>1 & length(ensemble)>1){
    stop(paste0("Only two out of 'sdate', 'time' and 'ensemble' can have a ",
                "length larger than one."))
  }else{
    
    # Faceting requirements
    facet_vars <- list(sdate = sdate, time = time, ensemble = ensemble)
    facet_vars <- names(facet_vars)[sapply(facet_vars, function(x) length(x) > 1)]
    f1 <- if (length(facet_vars) >= 1) facet_vars[1] else NULL
    f2 <- if (length(facet_vars) >= 2) facet_vars[2] else NULL
  }
  
  # Requirements: boundaries 
  if(!is.null(boundaries)){
    if(!inherits(boundaries, "sf")){
      if(boundaries != "countries"){
        stop("'boundaries' must be set to either 'countries' or be a polygon 'sf' object.")
      }
    }
  }
  
  # Number of panels
  if(length(time) * length(sdate) * length(ensemble) > 30){
    warning(paste0("The number of panels is very large, consider selecting a ",
                   "smaller set of times/ensemble members/start dates."))
  }
  
  # 2. Data preparation ----
  
  # Select 'sdate' if needed
  if(all(sdate %in% 1:dims_data["sdate"])){
    plot_data <- .subset_array_named(plot_data, sdate = sdate)
  }
  
  # Select 'time' if needed
  if(all(time %in% 1:dims_data["time"])){
    plot_data <- .subset_array_named(plot_data, time = time)
  }
  
  # Aggregate ensemble members if needed
  if((dims_data["ensemble"] > 1) & isTRUE(ensemble)){
    message(paste0("Aggregating ensemble members with the function: ", 
                   deparse(substitute(ensemble_fun))))
    keep_margins <- which(names(dims_data) != "ensemble")
    plot_data <- apply(plot_data, MARGIN = keep_margins, FUN = ensemble_fun)
    dim(plot_data) <- c(dim(plot_data), "ensemble"=1)
    ensemble <- 1
    
    # Select ensemble member
  }else if(all(ensemble %in% 1:dims_data["ensemble"])){
    plot_data <- .subset_array_named(plot_data, ensemble = ensemble)
  }
  
  # Select boundaries if needed
  if(!is.null(boundaries)){
    if(inherits(boundaries, "sf")){
      if(sf::st_crs(boundaries)$epsg != 4326){
        message("Transforming 'boundaries' to CRS EPSG 4326")
        bound_sf <- sf::st_transform(boundaries, crs = 4326)
      } else{
        bound_sf <- boundaries
      }
    } else if(boundaries == "countries"){
      data(world, package = "spData")
      bound_sf <- world
    }
  }
  
  # Identify reanalysis and transform 'time' dimension if needed
  if(dims_data["sdate"] == 1 & is.numeric(data$coords$sdate)){
    data$coords$time <- data$attrs$Dates
  }
  
  
  # 3. Conversion to stars ----
  if ("longitude" %in% names(dims_data)) { # Gridded data
    
    spatial_dims <- c(which(names(dim(plot_data)) == "longitude"),
                      which(names(dim(plot_data)) == "latitude"))
    plot_data <- aperm(plot_data, c(spatial_dims, setdiff(1:length(dims_data), spatial_dims)))
    plot_data <- stars::st_as_stars(plot_data)
    names(plot_data) <- data$attrs$Variable$varName
    plot_data <- stars::st_set_dimensions(plot_data, "longitude",
                                          values = c(data$coords$longitude))
    plot_data <- stars::st_set_dimensions(plot_data, "latitude",
                                          values = c(data$coords$latitude))
    sf::st_crs(plot_data) <- 4326
    
    # Mask if needed
    if(isTRUE(mask_boundaries) & !is.null(boundaries)){
      sf::sf_use_s2(FALSE) 
      suppressMessages(plot_data <- plot_data[bound_sf])
      sf::sf_use_s2(FALSE) 
    }
    
  } else if ("location" %in% names(dims_data)) { # Point data
    
    lon <- data$attrs$location$longitude
    lat <- data$attrs$location$latitude
    point_geom <- sf::st_sfc(lapply(seq_along(lon),
                                    function(i) sf::st_point(c(lon[i], lat[i]))),
                             crs = 4326) 
    plot_data <- stars::st_as_stars(plot_data,
                                    dimensions = stars::st_dimensions(
                                      dataset = c(data$coord$dataset),
                                      var = c(data$coord$var),
                                      sdate = c(data$coords$sdate)[sdate],
                                      time = c(data$coords$time)[time],
                                      ensemble = c(data$coords$ensemble)[ensemble],
                                      location = point_geom
                                    ))
    varname <- data$attrs$Variable$varName
    names(plot_data) <- varname
    plot_data <- st_as_sf(plot_data, long = TRUE)
    # plot_data <- plot_data[!is.na(sf::st_drop_geometry(plot_data)[,varname]),] # drop missing?
    
  } else if ("area" %in% names(dims_data)) { # Polygon data
    
    plot_data <- stars::st_as_stars(plot_data,
                                    dimensions = stars::st_dimensions(
                                      dataset = c(data$coord$dataset),
                                      var = c(data$coord$var),
                                      sdate = c(data$coords$sdate)[sdate],
                                      time = c(data$coords$time)[time],
                                      ensemble = c(data$coords$ensemble)[ensemble],
                                      area = data$attrs$area$geom
                                    ))
    varname <- data$attrs$Variable$varName
    names(plot_data) <- varname
    plot_data <- st_as_sf(plot_data, long = TRUE)
    
  }
  
  # 4. Plot ----
  
  # Base plot
  if ("longitude" %in% names(dims_data)) { # Gridded data
    p <- ggplot2::ggplot() +
      stars::geom_stars(data = plot_data, ...) +
      ggplot2::coord_equal(expand = FALSE)
    
  } else if ("location" %in% names(dims_data)) { # Point data
    if(!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::geom_sf(data = plot_data, ggplot2::aes(colour = .data[[varname]], ...))  +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    } else {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = plot_data, ggplot2::aes(colour = .data[[varname]], ...))  +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    }
    
  } else if ("area" %in% names(dims_data)) { # Polygon data
    if(!is.null(boundaries)) {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::geom_sf(data = plot_data, ggplot2::aes(fill = .data[[varname]]), 
                         ..., inherit.aes = FALSE) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_data)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_data)[c("ymin", "ymax")],
          expand = TRUE)   +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    } else {
      p <- ggplot2::ggplot() +
        ggplot2::geom_sf(data = plot_data, ggplot2::aes(fill = .data[[varname]]),
                         ...)   +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    }
  }
  
  # Faceting
  if(!is.null(f1) & is.null(f2)){ # Wrap
    p <- p +
      ggplot2::facet_wrap(as.formula(paste("~", f1)),
                          labeller = "label_both")
  }else if(!is.null(f1) & !is.null(f2)){ # Grid
    
    if(!isTRUE(coordgrid)) {
      p <- p +
        ggplot2::facet_grid(as.formula(paste(f1, "~", f2)),
                            labeller = "label_both", switch = "y")
    } else{
      p <- p +
        ggplot2::facet_grid(as.formula(paste(f1, "~", f2)), labeller = "label_both")      
    }

  }
  
  # Palette
  my_palette <- GHRexplore::GHR_palette(palette)(n = 30)
  if ("location" %in% names(dims_data)){
    p <- p + ggplot2::scale_colour_gradientn(colors = my_palette, na.value = "grey70")  
    
  }else if ("area" %in% names(dims_data)){
    p <- p + ggplot2::scale_fill_gradientn(colors = my_palette, na.value = "grey70")  
    
  }else {
    p <- p + ggplot2::scale_fill_gradientn(colors = my_palette, na.value = "#00000000")  
  }
  
  # Boundaries on top, only for grid
  if(!is.null(boundaries) & "longitude" %in% names(dims_data)){
    suppressMessages(
      p <- p +
        ggplot2::geom_sf(data = bound_sf, alpha = 0, 
                         col = "grey10", linewidth = 0.1, inherit.aes = FALSE) +
        ggplot2::coord_sf(
          xlim = sf::st_bbox(plot_data)[c("xmin", "xmax")],
          ylim = sf::st_bbox(plot_data)[c("ymin", "ymax")],
          expand = TRUE) +
        ggplot2::scale_x_continuous(labels = function(x) paste0(ifelse(x < 0, "-", ""), abs(x))) +
        ggplot2::scale_y_continuous(labels = function(y) paste0(ifelse(y < 0, "-", ""), abs(y)))
    )
  }
  
  # Theme
  if(isTRUE(coordgrid)) {

    p <- p +
      ggplot2::theme_minimal() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        panel.background =  ggplot2::element_rect(fill = NA, color = "grey10", linewidth = 0.2),
        panel.grid.minor = ggplot2::element_blank(),
        axis.ticks = ggplot2::element_line(linewidth = 0.3, color = "grey50"),
        axis.text = ggplot2::element_text(size = 7, color = "grey30"),
        axis.text.x = ggplot2::element_text(angle = -45, hjust = 0),
        strip.text.y = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        legend.key.height = ggplot2::unit(1, "cm")) +
      ggplot2::xlab("") + ggplot2::ylab("")
    
    if(!isTRUE(coordgrid)){
      p <- p +
        ggplot2::theme(strip.text.y = ggplot2::element_text(angle = 90))
    }
  } else {
    p <- p + 
      ggplot2::theme_void() +
      ggplot2::theme(
        plot.margin = ggplot2::theme_bw()$plot.margin,
        strip.text.y = ggplot2::element_text(angle = 90, margin = ggplot2::margin(b = 0)),
        strip.text.x = ggplot2::element_text(margin = ggplot2::margin(b = 0)),
        legend.key.height = ggplot2::unit(1, "cm"))
  }

  # Labels
  if(!is.null(title)){
    p <- p + ggplot2::ggtitle(title)
  }
  if(!is.null(legend)){
    if(!"location" %in% names(dims_data)) {
      p <- p + ggplot2::labs(fill = legend)
    } else {
      p <- p + ggplot2::labs(col = legend)
    }
  }
  if((!"sdate" %in% c(f1, f2)) & ("time" %in% c(f1, f2)) & is.numeric(data$coords$time)) {
    
    if("longitude" %in% names(dims_data)){
      subtitle <- paste0("Start date: ", 
                         stars::st_get_dimension_values(plot_stars, "sdate"))
    } else {
      subtitle <- paste0("Start date: ", plot_stars$sdate[1])
    }
    p <- p +
      ggplot2::labs(subtitle =  paste0(
        "Start date: ",
        stars::st_get_dimension_values(plot_stars, "sdate")))
  }
  
  return(p)
}